CREATE TABLE `orders` (
  `order_id` varchar(20) NOT NULL,
  `customer_id` varchar(20) DEFAULT NULL,
  `order_date` date DEFAULT NULL,
  `delivery_zone_id` varchar(10) DEFAULT NULL,
